INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (10, 0, 11, 19050041, 0, 107611, "シズルさまにエリコさま、\nどうかされたのですか？", 905, 1, 0.5, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", "", 91, 19050042, "", 0, "", 905, "", "", "");
