INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (10, 0, 11, 19440033, 0, 107911, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 944, 1, 1, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", "", 91, 19440034, "", 0, "", 944, "", "", "");
