INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", "", 21, 19450032, "", "vo_fpc", "vo_fpc_30504", 945, 0, "", "");
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (5, 0, 11, 19450033, 0, 122611, "…うん、やっちゃった…\nおっきなハートマーク…\nやっぱりこれは無しで！\nマコトちゃん食べてくれる！？", 945, 1, 1, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", "", 91, 19450034, "", 0, "", 945, "", "", "");
