INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (9, 0, 11, 19450037, 0, 110411, "わかったよ。あたしがついてって\nかわりに食ってやるから…\n他のおかずは自信作なんだろ？\nほら、早く行くぞ！", 945, 1, 0.5, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", "", 91, 19450038, "", 0, "", 945, "", "", "");
